const r = $input.first().json;
const toolCalls = Array.isArray(r.toolCalls) ? r.toolCalls : [];

const nestedCounts = function (obj, prefix, depth, acc) {
  if (depth > 2 || !obj || typeof obj !== 'object' || Array.isArray(obj)) return acc;
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    const path = prefix ? prefix + '.' + k : k;
    if (Array.isArray(v)) {
      if (Object.keys(acc).length < 20) acc[path] = { kind: 'array', count: v.length };
    } else if (v && typeof v === 'object') {
      nestedCounts(v, path, depth + 1, acc);
    }
  }
  return acc;
};

const shapeOfParsed = function (parsed) {
  if (Array.isArray(parsed)) {
    const first = parsed[0];
    const shape = {
      kind: 'array',
      count: parsed.length,
      itemKeys: first && typeof first === 'object' && !Array.isArray(first) ? Object.keys(first) : null,
    };
    if (first && typeof first === 'object' && !Array.isArray(first)) shape.nested = nestedCounts(first, '', 0, {});
    return shape;
  }
  if (parsed && typeof parsed === 'object') return { kind: 'object', keys: Object.keys(parsed), nested: nestedCounts(parsed, '', 0, {}) };
  return { kind: typeof parsed };
};

// Normalise messageAnAgent tool results to the observation shape the
// evaluator already understands (array of row objects, like the old
// intermediateSteps observations). Workflow tool results arrive wrapped
// under the sub-workflow's FINAL NODE NAME (e.g. data['Shape Output'] =
// [{results, meta}]); node tools arrive as [{json, pairedItem}] items.
const normalizeData = function (data) {
  if (data == null) return null;
  let env = data;
  if (env && typeof env === 'object' && !Array.isArray(env) && !Array.isArray(env.results)) {
    const keys = Object.keys(env);
    if (keys.length === 1) env = env[keys[0]];
  }
  if (Array.isArray(env)) {
    const items = env.map(function (x) { return (x && typeof x === 'object' && x.json !== undefined) ? x.json : x; });
    if (items.length === 1 && items[0] && typeof items[0] === 'object' && Array.isArray(items[0].results)) {
      return items[0].results;
    }
    return items;
  }
  if (env && typeof env === 'object') {
    if (Array.isArray(env.results)) return env.results;
    return [env];
  }
  return env;
};

const toolsUsed = [];
const outcomes = [];
for (const t of toolCalls) {
  const name = t && t.toolName;
  if (!name) continue;
  if (!toolsUsed.includes(name)) toolsUsed.push(name);
  const res = t.result;
  let ok = false;
  let shape = { kind: 'null' };
  if (res && typeof res === 'object' && !Array.isArray(res)) {
    ok = res.status === undefined || res.status === 'success';
    const norm = normalizeData(res.data);
    shape = norm === null ? { kind: 'null' } : shapeOfParsed(norm);
  } else if (typeof res === 'string' && res.trim() !== '') {
    ok = true;
    try { shape = shapeOfParsed(JSON.parse(res)); } catch (e) { shape = { kind: 'string' }; }
  } else if (res !== undefined && res !== null) {
    ok = true;
    shape = shapeOfParsed(res);
  }
  outcomes.push({ tool: name, ok, shape });
}

const startedAt = Number($('Stamp Start').item.json.started_at_ms) || null;
return [{ json: {
  output: typeof r.text === 'string' ? r.text : (r.output || ''),
  tools_used: toolsUsed,
  tool_outcomes: outcomes,
  usage: r.usage || null,
  session_id: r.session && r.session.sessionId ? r.session.sessionId : '',
  finish_reason: r.finishReason || null,
  duration_ms: startedAt ? (Date.now() - startedAt) : null,
} }];

const c = $('Load Case').item.json;
const runId = $('Case Input').item.json.run_id;
const r = $input.first().json;
let status = 'pass';
let answer = '';
let called = [];

if (r && r.error) {
  status = 'error';
  answer = typeof r.error === 'string' ? r.error : JSON.stringify(r.error);
} else {
  if (typeof r.output === 'string') {
    answer = r.output;
  } else if (r.output !== undefined) {
    answer = JSON.stringify(r.output);
  } else {
    answer = JSON.stringify(r);
  }
  if (Array.isArray(r.tools_used)) {
    called = r.tools_used;
  } else if (Array.isArray(r.intermediateSteps)) {
    for (const s of r.intermediateSteps) {
      const t = s && s.action && s.action.tool;
      if (t) called.push(t);
    }
  }
  if (!answer) status = 'error';
}

const norm = function (s) { return String(s).toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, ''); };
const calledN = [];
for (const t of called) { const n = norm(t); if (!calledN.includes(n)) calledN.push(n); }

// Tool observations arrive in one of two shapes:
// - Builder: compact tool_outcomes[] computed by its Format Output node
// - Darwin: raw intermediateSteps[] (the agent output is forwarded unmodified)
const steps = Array.isArray(r.intermediateSteps) ? r.intermediateSteps : [];
const outcomes = Array.isArray(r.tool_outcomes) ? r.tool_outcomes : null;

const isErrorObs = function (obs) {
  if (obs == null) return true;
  const s = String(obs).trim();
  if (s === '') return true;
  let parsed;
  try { parsed = JSON.parse(s); } catch (e) { return false; }
  const arr = Array.isArray(parsed) ? parsed : [parsed];
  return arr.length > 0 && arr.every(x => x && typeof x === 'object' && 'error' in x);
};

const nestedCounts = function (obj, prefix, depth, acc) {
  if (depth > 2 || !obj || typeof obj !== 'object' || Array.isArray(obj)) return acc;
  for (const k of Object.keys(obj)) {
    const v = obj[k];
    const path = prefix ? prefix + '.' + k : k;
    if (Array.isArray(v)) {
      if (Object.keys(acc).length < 20) acc[path] = { kind: 'array', count: v.length };
    } else if (v && typeof v === 'object') {
      nestedCounts(v, path, depth + 1, acc);
    }
  }
  return acc;
};

const shapeOfParsed = function (parsed) {
  if (Array.isArray(parsed)) {
    const first = parsed[0];
    const shape = {
      kind: 'array',
      count: parsed.length,
      itemKeys: first && typeof first === 'object' && !Array.isArray(first) ? Object.keys(first) : null,
    };
    if (first && typeof first === 'object' && !Array.isArray(first)) shape.nested = nestedCounts(first, '', 0, {});
    return shape;
  }
  if (parsed && typeof parsed === 'object') return { kind: 'object', keys: Object.keys(parsed), nested: nestedCounts(parsed, '', 0, {}) };
  return { kind: typeof parsed };
};

const shapeOfObs = function (obs) {
  if (obs == null) return { kind: 'null' };
  const s = String(obs).trim();
  if (s === '') return { kind: 'empty' };
  try { return shapeOfParsed(JSON.parse(s)); } catch (e) { return { kind: 'string' }; }
};

// 'ok' | 'failed' | 'not_called' — ok if ANY call to the tool returned real output.
const toolOutcome = function (toolRaw) {
  const n = norm(toolRaw);
  if (outcomes) {
    const hit = outcomes.find(o => norm(o.tool) === n);
    if (!hit) return 'not_called';
    return hit.ok ? 'ok' : 'failed';
  }
  const hits = steps.filter(s => s && s.action && norm(s.action.tool) === n);
  if (!hits.length) return 'not_called';
  return hits.every(s => isErrorObs(s.observation)) ? 'failed' : 'ok';
};

// Shape summary for a tool, from tool_outcomes (Builder) or intermediateSteps (Darwin).
const obsForTool = function (toolRaw) {
  const n = norm(toolRaw);
  if (outcomes) {
    const hit = outcomes.find(o => norm(o.tool) === n);
    return hit ? hit.shape : null;
  }
  const hits = steps.filter(s => s && s.action && norm(s.action.tool) === n);
  if (!hits.length) return null;
  return shapeOfObs(hits[hits.length - 1].observation);
};

// Structural predicate match. pred: { kind, minItems, maxItems, hasKeys, missingKeys,
// nested: { path, kind, minItems, maxItems } }
const matchShape = function (shape, pred) {
  if (!shape) return false;
  if (pred.kind && shape.kind !== pred.kind) return false;
  if (pred.minItems != null && (shape.count == null || shape.count < pred.minItems)) return false;
  if (pred.maxItems != null && (shape.count == null || shape.count > pred.maxItems)) return false;
  const keys = shape.itemKeys || shape.keys || [];
  if (Array.isArray(pred.hasKeys) && !pred.hasKeys.every(k => keys.includes(k))) return false;
  if (Array.isArray(pred.missingKeys) && pred.missingKeys.some(k => keys.includes(k))) return false;
  if (pred.nested && pred.nested.path) {
    const n = shape.nested ? shape.nested[pred.nested.path] : undefined;
    if (!n) return false;
    if (pred.nested.kind && n.kind !== pred.nested.kind) return false;
    if (pred.nested.minItems != null && (n.count == null || n.count < pred.nested.minItems)) return false;
    if (pred.nested.maxItems != null && (n.count == null || n.count > pred.nested.maxItems)) return false;
  }
  return true;
};

let assertions = [];
try {
  assertions = typeof c.assertions === 'string' ? JSON.parse(c.assertions) : (c.assertions || []);
} catch (e) {
  status = 'error';
}

const answerN = answer.toLowerCase();
const results = [];
if (status !== 'error') {
  for (const a of assertions) {
    let pass = false;
    let known = true;
    if (a.type === 'tool_called') pass = calledN.includes(norm(a.value));
    else if (a.type === 'tool_not_called') pass = !calledN.includes(norm(a.value));
    else if (a.type === 'contains') pass = answerN.includes(String(a.value).toLowerCase());
    else if (a.type === 'not_contains') pass = !answerN.includes(String(a.value).toLowerCase());
    else if (a.type === 'tool_succeeded') pass = toolOutcome(a.value) === 'ok';
    else if (a.type === 'tool_failed') pass = toolOutcome(a.value) === 'failed';
    else if (a.type === 'response_shape') pass = matchShape(obsForTool(a.tool || a.value), a.shape || {});
    else known = false;
    if (!known) {
      // Unknown assertion types are a case-authoring bug — mark the case errored, not failed.
      status = 'error';
      results.push({ type: a.type, value: a.value, tool: a.tool, pass: false, error: 'unknown assertion type' });
      continue;
    }
    if (!pass) status = 'fail';
    results.push({ type: a.type, value: a.value, tool: a.tool, pass: pass });
  }
}

return [{ json: {
  run_id: runId,
  case_id: c.id,
  slug: c.slug,
  status: status,
  called_tools: calledN,
  output: answer.slice(0, 4000),
  assertion_results: results,
  session_id: 'integration-' + runId + '-' + c.id
} }];
